{

    internal InnerEvaluatorBedrockEvaluatorModelConfigFactory BedrockEvaluatorModelConfigFactory { get; set; }

    internal InnerEvaluatorOpenResponsesEvaluatorModelConfigFactory ResponsesEvaluatorModelConfigFactory { get; set; }

    protected override Humidifier.BedrockAgentCore.EvaluatorTypes.EvaluatorModelConfig Create()
    {
        var evaluatorModelConfigResult = CreateEvaluatorModelConfig();
        factoryAction?.Invoke(evaluatorModelConfigResult);

        return evaluatorModelConfigResult;
    }

    private Humidifier.BedrockAgentCore.EvaluatorTypes.EvaluatorModelConfig CreateEvaluatorModelConfig()
    {
        var evaluatorModelConfigResult = new Humidifier.BedrockAgentCore.EvaluatorTypes.EvaluatorModelConfig();

        return evaluatorModelConfigResult;
    }
    public override void CreateChildren(Humidifier.BedrockAgentCore.EvaluatorTypes.EvaluatorModelConfig result)
    {
        base.CreateChildren(result);

        result.BedrockEvaluatorModelConfig ??= BedrockEvaluatorModelConfigFactory?.Build();
        result.ResponsesEvaluatorModelConfig ??= ResponsesEvaluatorModelConfigFactory?.Build();
    }

} // End Of Class

